/**
 * [LY-P0] قواعد §3/§4 — **خالصة**، فتُختبر في الحزمة السريعة بلا قاعدة بيانات.
 *
 * لماذا هنا لا في الدورة: هذه قرارات أعمال لا استعلامات. فصلُها يجعلها قابلة للاختبار
 * بلا Postgres — وهو ما تلزم به القاعدة ٨ فعليًا (لا قاعدة بيانات محليّة، فما لا يُفصل
 * لا يُختبر إلّا في CI).
 */
/**
 * BR-L3.1 — برنامجٌ فعّالٌ واحد لكل أكاديمية.
 *
 * لا يُفرض بقيدٍ جزئي في المخطط: Prisma لا يُعبّر عن `CREATE UNIQUE INDEX … WHERE`،
 * وكتابةُ القيد يدويًا في الهجرة كانت ستُنتج مخططًا لا يصفه `schema.prisma` — وهو ما
 * يكسر `prisma migrate diff` في كل مرحلةٍ تالية. فيُفرض هنا ويُختبر.
 *
 * الرسالة تُسمّي البرنامج القائم لأنّ «برنامجٌ فعّال موجود» وحدها لا تقول للمستخدم
 * ماذا يفعل؛ واسمُه هو ما يبحث عنه ليعطّله.
 */
export declare function assertSingleActiveProgram(activePrograms: {
    id: string;
    name: string;
}[], selfId?: string): void;
/**
 * BR-L3.3 — لا حذف صلب ما دام هناك مرجع؛ التعطيل هو البديل.
 *
 * في LY-P0 لا جدول يشير إلى البرنامج غير `loyalty_tier` (ابنُه، يُحذف معه بالتتالي)،
 * فالعدّ صفرٌ دائمًا اليوم. والدالة موجودة لأنّ LY-P1 يملؤها بدفتر النقاط، ولأنّ
 * السلوك المُختبَر يجب أن يكون سلوك القاعدة لا سلوك الفراغ.
 */
export declare function assertProgramDeletable(referenceCount: number, programName: string): void;
/**
 * §4 — تماسك المستويات داخل البرنامج الواحد.
 *
 * **الترتيب والإنفاق يجب أن يصعدا معًا.** مستوًى أعلى ترتيبًا بإنفاقٍ مؤهِّل أقلّ يجعل
 * الاشتقاق في LY-P3 غامضًا: وليّ أمرٌ أنفق ٥٠٠ يصير مؤهَّلًا لمستويين، ولا شيء يقول أيّهما
 * يفوز. يُرفض هنا بدل أن يُكتشف بعد مرحلتين حين تُبنى الحاسبة.
 *
 * تُفحص المجموعة كاملةً لا الصفّ وحده: القاعدة علاقةٌ بين صفوف، ولا يمكن لصفٍّ منفرد
 * أن يعرف إن كان يكسرها.
 */
export declare function assertTierLadder(tiers: {
    id?: string;
    name: string;
    order: number;
    minSpend: number;
}[]): void;
/** §4 — اللون مفتاح رمزٍ من القائمة المغلقة، لا قيمة hex (§17.2 صفّ ٢ من CRM). */
export declare function assertColorToken(token: string): void;
